// news-image-20261125 — "Sum up 25 November's world news in one image"
// One-page newspaper, 1024x1024 PNG, deterministic, Node 22 stdlib-only.
// Text: ALL CAPS, filled DejaVu Serif glyphs baked at build time (see tools/bake_font.py).
// No network, no clock, no randomness. Two runs must be byte-identical.
// Layout: masthead -> kicker -> stat strip -> region strip -> timeline
//          -> 3 illustrated heroes -> 10 small cards -> map + ALSO ON briefs
//          -> DATE CHECK -> legend + footer.

import * as fs from "node:fs";
