const faces = new Map<string, Face>();
function getFace(name: string): Face {
  let f = faces.get(name);
  if (!f) {
    const raw = FONT_DATA[name];
    if (!raw) throw new Error("missing font face " + name);
    f = { data: Buffer.from(raw.data, "base64"), tab: raw.tab, cap_h: raw.cap_h };
    faces.set(name, f);
  }
  return f;
}
// The baked tab rows are ordered by the charset string stored in the manifest.
// We keep the charset in a const and map char -> row index.
let FONT_CHARSET = " !$%(),-./0123456789:=ABCDEFGHIJKLMNOPRSTUVWXYZ|";
function glyphRow(face: Face, ch: string): number[] | null {
  const idx = FONT_CHARSET.indexOf(ch);
  if (idx < 0) return null;
  return face.tab[idx] || null;
}
function textWidth(faceName: string, s: string): number {
  const f = getFace(faceName);
  let w = 0;
  for (const ch of s) {
    const row = glyphRow(f, ch);
    if (!row) throw new Error("glyph missing: " + JSON.stringify(ch) + " in " + faceName);
    w += row[0];
  }
  return w;
}
function drawText(faceName: string, x: number, yTop: number, s: string, c: RGB): void {
  const f = getFace(faceName);
  let cx = Math.round(x);
  for (const ch of s) {
    const row = glyphRow(f, ch);
    if (!row) throw new Error("glyph missing: " + JSON.stringify(ch) + " in " + faceName);
    const [adv, xoff, yoff, gw, gh, off] = row;
    for (let gy = 0; gy < gh; gy++) {
      for (let gx = 0; gx < gw; gx++) {
        const byte = f.data[off + Math.floor((gy * gw + gx) / 2)];
        const nib = ((gy * gw + gx) % 2 === 0) ? (byte >> 4) & 15 : byte & 15;
        if (nib === 0) continue;
        const a = nib / 15;
        const pxX = cx + xoff + gx, pxY = Math.round(yTop) + yoff + gy;
        if (pxX < 0 || pxY < 0 || pxX >= W || pxY >= H) continue;
        const i = (pxY * W + pxX) * 3;
        img[i] = Math.round(img[i] * (1 - a) + c[0] * a);
        img[i + 1] = Math.round(img[i + 1] * (1 - a) + c[1] * a);
        img[i + 2] = Math.round(img[i + 2] * (1 - a) + c[2] * a);
      }
    }
    cx += adv;
  }
}
function drawTextC(faceName: string, cx: number, yTop: number, s: string, c: RGB): void {
  drawText(faceName, cx - textWidth(faceName, s) / 2, yTop, s, c);
}
function drawTextR(faceName: string, rx: number, yTop: number, s: string, c: RGB): void {
  drawText(faceName, rx - textWidth(faceName, s), yTop, s, c);
}
function wrap(faceName: string, s: string, maxW: number): string[] {
  const words = s.split(" ");
  const lines: string[] = [];
  let cur = "";
  for (const w of words) {
    const cand = cur ? cur + " " + w : w;
    if (textWidth(faceName, cand) <= maxW) { cur = cand; continue; }
    if (cur) lines.push(cur);
    cur = w;
  }
  if (cur) lines.push(cur);
  return lines;
}

// ---------------------------------------------------------------- PNG
const CRC_TABLE: number[] = [];
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  CRC_TABLE[n] = c >>> 0;
}
function crc32(buf: Buffer): number {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function chunk(type: string, data: Buffer): Buffer {
  const out = Buffer.alloc(12 + data.length);
  out.writeUInt32BE(data.length, 0);
  out.write(type, 4, "ascii");
  data.copy(out, 8);
  out.writeUInt32BE(crc32(Buffer.concat([Buffer.from(type, "ascii"), data])), 8 + data.length);
  return out;
}
function encodePNG(): Buffer {
  const raw = Buffer.alloc(H * (1 + W * 3));
  for (let y = 0; y < H; y++) {
    raw[y * (1 + W * 3)] = 0;
    raw.set(img.subarray(y * W * 3, (y + 1) * W * 3), y * (1 + W * 3) + 1);
  }
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(W, 0); ihdr.writeUInt32BE(H, 4);
  ihdr[8] = 8; ihdr[9] = 2; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw, { level: 9 })),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}

